const { withMod } = require('@expo/config-plugins');

// SDK 54's image-free splash path leaves the template's background and image constraints.
// Keep the named color reference so iOS can select the light/dark asset generated by Expo.
function applyPlainSplash(storyboard, backgroundColor) {
  const document = storyboard.document;
  const view = document.scenes[0].scene[0].objects[0].viewController[0].view[0];
  for (const group of view.subviews || []) {
    group.imageView = (group.imageView || []).filter((image) => image.$.id !== 'EXPO-SplashScreen');
  }
  for (const group of view.constraints || []) {
    group.constraint = (group.constraint || []).filter(
      (constraint) =>
        constraint.$.firstItem !== 'EXPO-SplashScreen' &&
        constraint.$.secondItem !== 'EXPO-SplashScreen',
    );
  }
  view.color = [{ $: { key: 'backgroundColor', name: 'SplashScreenBackground' } }];
  const resources = document.resources[0];
  resources.image = (resources.image || []).filter(
    (image) => !['SplashScreen', 'SplashScreenLogo', 'SplashScreenLegacy'].includes(image.$.name),
  );
  const rgb = backgroundColor
    .slice(1)
    .match(/.{2}/g)
    .map((channel) => parseInt(channel, 16) / 255);
  resources.namedColor = [
    ...(resources.namedColor || []).filter((color) => color.$.name !== 'SplashScreenBackground'),
    {
      $: { name: 'SplashScreenBackground' },
      color: [
        {
          $: {
            red: rgb[0],
            green: rgb[1],
            blue: rgb[2],
            alpha: 1,
            colorSpace: 'custom',
            customColorSpace: 'sRGB',
          },
        },
      ],
    },
  ];
  return storyboard;
}

module.exports = function withPlainSplash(config) {
  // Register before expo-splash-screen adds its provider; mod actions then run in reverse order.
  const splash = config.plugins.find(
    (plugin) => Array.isArray(plugin) && plugin[0] === 'expo-splash-screen',
  )?.[1];
  // A future approved transparent mark uses Expo's normal image path instead.
  if (!splash || splash.image || config.splash?.image) return config;
  if (!/^#[0-9a-f]{6}$/i.test(splash.backgroundColor)) {
    throw new Error('The plain splash requires a six-digit background color.');
  }
  return withMod(config, {
    platform: 'ios',
    mod: 'splashScreenStoryboard',
    action: (mod) => {
      mod.modResults = applyPlainSplash(mod.modResults, splash.backgroundColor);
      return mod;
    },
  });
};
module.exports.applyPlainSplash = applyPlainSplash;
